messages.content:
Tool response:
Tool: add_line_comment
Description: Add Line Comment
Parameters:
    {
      "type": "object",
      "properties": {
        "submission_id": {
          "type": "string",
          "description": "Unique identifier of the submission",
          "title": "Submission Id"
        },
        "file_id": {
          "type": "integer",
          "title": "File Id",
          "description": "Internal ID of the file within the submission"
        },
        "line_number": {
          "type": "integer",
          "exclusiveMinimum": 0.0,
          "title": "Line Number",
          "description": "Line number where the comment is placed (must be greater than 0)"
        },
        "comment_text": {
          "type": "string",
          "title": "Comment Text",
          "description": "Text content of the comment"
        },
        "severity": {
          "type": "string",
          "title": "Severity",
          "description": "Severity level of the comment (info, minor, major, critical)"
        }
      },
      "required": [
        "submission_id",
        "file_id",
        "line_number",
        "comment_text",
        "severity"
      ]
    }

Tool response:
Tool: request_resubmission
Description: Request Resubmission
Parameters:
    {
      "type": "object",
      "properties": {
        "submission_id": {
          "type": "string",
          "description": "Unique identifier of the submission",
          "title": "Submission Id"
        },
        "deadline": {
          "type": "string",
          "title": "Deadline",
          "description": "Deadline date for the resubmission in YYYY-MM-DD format"
        }
      },
      "required": [
        "submission_id",
        "deadline"
      ]
    }
